/* systemsvc.CommonCodeMapper.insertCommonCodeGroup(공통코드 그룹 등록) */
INSERT INTO common_code_groups (
    group_cd
    ,group_nm
    ,group_desc
    ,system_yn
    ,use_yn
    ,sort_seq
    ,created_by
    ,created_at
    ,updated_by
    ,updated_at
)
VALUES (
    #{request.data.groupCd}
    ,#{request.data.groupNm}
    ,#{request.data.groupDesc}
    ,COALESCE(#{request.data.systemYn}, 'N')
    ,COALESCE(#{request.data.useYn}, 'Y')
    ,COALESCE(#{request.data.sortSeq}, 0)
    ,#{createdBy}
    ,current_timestamp
    ,#{createdBy}
    ,current_timestamp
)

mapper.update:

/* systemsvc.CommonCodeMapper.updateCommonCodeGroup(공통코드 그룹 수정) */
UPDATE common_code_groups
SET group_nm = #{request.data.groupNm}
    ,group_desc = #{request.data.groupDesc}
    ,system_yn = COALESCE(#{request.data.systemYn}, system_yn)
    ,use_yn = COALESCE(#{request.data.useYn}, use_yn)
    ,sort_seq = COALESCE(#{request.data.sortSeq}, sort_seq)
    ,updated_by = #{updatedBy}
    ,updated_at = current_timestamp
WHERE group_cd = #{groupCd}

mapper.select:
/* systemsvc.CommonCodeMapper.findCommonCodeDetails(공통코드 상세 항목 목록 조회) */ SELECT g.group_cd ,c.code ,c.code_nm ,c.code_desc ,c.sort_seq ,c.use_yn ,c.created_by ,c.updated_by ,c.created_at ,c.updated_at FROM common_codes c INNER JOIN common_code_groups g ON c.group_id = g.group_id
AND g.group_cd = #{groupCd}
ORDER BY c.sort_seq, c.code

mapper.delete:

/* systemsvc.CommonCodeMapper.deleteCommonCodesByGroupCd(공통코드 일괄 교체 전 삭제) */
DELETE FROM common_codes c
USING common_code_groups g
WHERE c.group_id = g.group_id
  AND g.group_cd = #{groupCd}


/* systemsvc.CommonCodeMapper.deleteCommonCodeGroup(공통코드 그룹 삭제) */
DELETE FROM common_code_groups
WHERE group_cd = #{groupCd}

mapper.insert:
/* systemsvc.CommonCodeMapper.insertCommonCodes(공통코드 일괄 교체 등록) */ INSERT INTO common_codes ( group_id ,code ,code_nm ,code_desc ,parent_code_id ,sort_seq ,use_yn ,valid_from ,valid_to ,extra_data ,created_by ,created_at ,updated_by ,updated_at ) SELECT g.group_id ,v.code ,v.code_nm ,v.code_desc ,NULL AS parent_code_id ,COALESCE(v.sort_seq, 0) ,COALESCE(v.use_yn, 'Y') ,v.valid_from ,v.valid_to ,CAST(COALESCE(v.extra_data, '{}') AS jsonb) ,#{createdBy} ,current_timestamp ,#{createdBy} ,current_timestamp FROM common_code_groups g CROSS JOIN ( VALUES
( CAST(#{item.code} AS varchar) ,CAST(#{item.codeNm} AS varchar) ,CAST(#{item.codeDesc} AS varchar) ,CAST(#{item.sortSeq} AS integer) ,CAST(#{item.useYn} AS varchar) ,CAST(#{item.validFrom} AS date) ,CAST(#{item.validTo} AS date) ,CAST(#{item.extraData} AS text) )
) AS v(code, code_nm, code_desc, sort_seq, use_yn, valid_from, valid_to, extra_data) WHERE g.group_cd = #{groupCd}

mapper.update:

/* systemsvc.CommonCodeMapper.updateReferenceDataVersion(기준정보 최신 버전 갱신) */
UPDATE reference_data_versions
SET version_no = CONCAT(
        split_part(version_no, '.', 1),
        '.',
        split_part(version_no, '.', 2),
        '.',
        (COALESCE(NULLIF(split_part(version_no, '.', 3), ''), '0')::integer + 1)::text
    )
    ,last_changed_at = current_timestamp
    ,last_changed_by = #{changedBy}
    ,remark = #{remark}
    ,updated_at = current_timestamp
    ,updated_by = #{changedBy}
WHERE ref_type = #{refType}
